css:
:root {
  --equipment-border: #01524F;

  --equipment-fill-light: #EDF7F5;
  --equipment-fill-middle: #D3E8E2;
  --equipment-fill-base: #BDDBD4;
}

html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;
  border: none;

  background: transparent !important;
  pointer-events: none;
}

.equipment-widget,
.equipment-widget * {
  box-sizing: border-box;
}

.equipment-widget {
  position: relative;
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;

  background: transparent;
  opacity: var(--w-opacity, 1);
  pointer-events: none;
  user-select: none;
}

.equipment-button {
  position: absolute;
  inset: 0;

  display: block;
  width: 100%;
  height: 100%;
  min-width: 0;
  min-height: 0;
  margin: 0;
  padding: 0;

  appearance: none;
  border: none;
  background: transparent;

  pointer-events: none;
  cursor: pointer;
  user-select: none;
  touch-action: manipulation;
  -webkit-tap-highlight-color: transparent;
}

.equipment-svg {
  display: block;
  width: 100%;
  height: 100%;
  overflow: hidden;

  background: transparent;
  shape-rendering: geometricPrecision;
  pointer-events: none;
}

.equipment-drawing {
  transform-box: view-box;
  transform-origin: 50% 50%;
  transform: scale(1);
  pointer-events: none;
}

.equipment-fill-light {
  stop-color: var(--equipment-fill-light);
}

.equipment-fill-middle {
  stop-color: var(--equipment-fill-middle);
}

.equipment-fill-base {
  stop-color: var(--equipment-fill-base);
}

.equipment-fill-light,
.equipment-fill-middle,
.equipment-fill-base {
  transition: stop-color 120ms ease;
}

.equipment-body,
.equipment-shaft {
  stroke: var(--equipment-border);
  stroke-width: 1.5;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.equipment-body {
  fill: url("#equipment-surface");
}

.equipment-shaft {
  fill: url("#equipment-shaft-surface");
}

.equipment-grooves {
  fill: none;
  stroke: var(--equipment-border);
  stroke-width: 1.1;
  stroke-linecap: round;
}

.equipment-highlight {
  fill: none;
  stroke: #FFFFFF;
  stroke-width: 1.1;
  stroke-linecap: round;
  opacity: 0.65;

  transition: opacity 120ms ease;
}

.equipment-block-highlight {
  stroke-width: 0.65;
}

.equipment-inner-shadow {
  fill: none;
  stroke: var(--equipment-border);
  stroke-width: 1.5;
  stroke-linecap: round;
  opacity: 0.12;

  transition: opacity 120ms ease;
}

.equipment-pressed-shadow {
  fill: none;
  stroke: var(--equipment-border);
  stroke-width: 1.6;
  stroke-linecap: round;
  opacity: 0;

  transition: opacity 120ms ease;
}

/* Solo el dibujo recibe el puntero dentro del widget. */
.equipment-hit-area {
  fill: transparent;
  stroke: transparent;
  stroke-width: 1.5;
  stroke-linejoin: round;

  pointer-events: all;
  cursor: pointer;
}

@media (hover: hover) {
  .equipment-button:hover {
    --equipment-fill-light: #F5FCFA;
    --equipment-fill-middle: #DDEFE9;
    --equipment-fill-base: #C8E3DB;
  }

  .equipment-button:hover .equipment-highlight {
    opacity: 0.85;
  }
}

/* Hundimiento centrado mientras se mantiene presionado. */
.equipment-button:active {
  --equipment-fill-light: #D5E8E2;
  --equipment-fill-middle: #C9E1D9;
  --equipment-fill-base: #B9D8CE;
}

.equipment-button:active .equipment-drawing {
  transform: scale(0.98);
}

.equipment-button:active .equipment-highlight {
  opacity: 0.25;
}

.equipment-button:active .equipment-pressed-shadow {
  opacity: 0.28;
}

.equipment-button:active .equipment-inner-shadow {
  opacity: 0.06;
}

.equipment-button:focus-visible {
  outline: none;
}

.equipment-button:focus-visible .equipment-body {
  stroke-width: 2;
}

@media (prefers-reduced-motion: reduce) {
  .equipment-fill-light,
  .equipment-fill-middle,
  .equipment-fill-base,
  .equipment-highlight,
  .equipment-inner-shadow,
  .equipment-pressed-shadow {
    transition: none;
  }
}

