"use strict";

(function () {
  let button = null;
  let latestWidget = window.WIDGET || {};

  function render(widget) {
    if (!button) {
      return;
    }

    const name =
      typeof widget.name === "string"
        ? widget.name.trim()
        : "";

    // Nombre accesible, sin texto visible sobre el símbolo.
    button.setAttribute(
      "aria-label",
      name || "Equipo con eje"
    );
  }

  window.onWidgetUpdate = function (widget) {
    latestWidget = widget || {};
    render(latestWidget);
  };

  function initialize() {
    button = document.querySelector(".equipment-button");
    render(latestWidget);
  }

  if (document.readyState === "loading") {
    document.addEventListener(
      "DOMContentLoaded",
      initialize,
      { once: true }
    );
  } else {
    initialize();
  }

  /*
   * Sin variables del PLC.
   * Hover y pulsación gestionados mediante CSS.
   * El SVG mantiene la relación de aspecto.
   * No se configura ninguna acción de control al hacer clic.
   */
})();
